-- Operational state only. Closed by default; no business or identity seed data.
CREATE TABLE migration_control (id INTEGER PRIMARY KEY CHECK(id=1), writes_enabled INTEGER NOT NULL CHECK(writes_enabled IN (0,1)));
INSERT INTO migration_control(id,writes_enabled) VALUES(1,0);
CREATE TRIGGER "fence_user_insert" BEFORE INSERT ON "user" BEGIN SELECT CASE WHEN (SELECT writes_enabled FROM migration_control WHERE id=1) IS NOT 1 THEN RAISE(ABORT,'Application writes are paused') END; END;
CREATE TRIGGER "fence_user_update" BEFORE UPDATE ON "user" BEGIN SELECT CASE WHEN (SELECT writes_enabled FROM migration_control WHERE id=1) IS NOT 1 THEN RAISE(ABORT,'Application writes are paused') END; END;
CREATE TRIGGER "fence_user_delete" BEFORE DELETE ON "user" BEGIN SELECT CASE WHEN (SELECT writes_enabled FROM migration_control WHERE id=1) IS NOT 1 THEN RAISE(ABORT,'Application writes are paused') END; END;
